            if i==len(xs)-1: vals.extend(self.eval_multi(x,env))
            else: vals.append(self.eval_expr(x,env))
        return vals
    def eval_multi(self,node,env):
        if node[0] in ('call','methodcall','vararg'): return self.eval_call_or_vararg(node,env)
        return [self.eval_expr(node,env)]
    def eval_expr(self,node,env):
        k=node[0]
        if k=='number': return node[1]
        if k=='string': return node[1]
        if k=='bool': return node[1]
        if k=='nil': return None
        if k=='var': return env.get(node[1])
        if k=='vararg':
            vv=env.get('...'); return vv[0] if isinstance(vv,list) and vv else None
        if k=='index': return self.get_index(self.eval_expr(node[1],env), self.eval_expr(node[2],env))
        if k in ('call','methodcall'): return (self.eval_call_or_vararg(node,env)+[None])[0]
        if k=='func': return LuaFunction(node[1],node[2],node[3],env)
        if k=='table':
            t=LuaTable(); idx=1
            for f in node[1]:
