# CLI

def make_arg_table(argv, script_index):
    t=LuaTable()
    for i,a in enumerate(argv): t.rawset(i-script_index,a)
    return t

def print_usage(prog): sys.stderr.write(USAGE.format(prog=prog)+'\n')

def report_error(prog,e):
    msg=str(e)
    if msg.startswith('cannot open '): sys.stderr.write(f"{prog}: {msg}\n")
    else:
        sys.stderr.write(f"{prog}: {msg}\nstack traceback:\n\t[C]: in function 'error'\n\t(command line):1: in main chunk\n\t[C]: at 0x000000000000\n")

def run_repl(I,prog):
    sys.stdout.write(JIT_VERSION+' -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/\n')
    while True:
        try:
            sys.stdout.write('> '); sys.stdout.flush(); line=sys.stdin.readline()
            if line=='': break
            if line.startswith('='): line='return '+line[1:]
            try:
                vals=I.run_chunk(line,'stdin')
                if vals: sys.stdout.write('\t'.join(lua_tostring(x) for x in vals)+'\n')
            except Exception as e: sys.stderr.write(f"{prog}: {e}\n")
        except KeyboardInterrupt: break

def main(argv):
    prog=argv[0] if argv else './executable'; args=argv[1:]
    I=Interpreter(prog)
    actions=[]; interactive=False; ignore_env=False; script=None; script_i=None; show_ver=False
    i=0
    while i<len(args):
        a=args[i]
        if a=='--':
            i+=1
            if i<len(args): script=args[i]; script_i=i+1
            break
        if a=='-': script='-'; script_i=i+1; break
        if not a.startswith('-') or a=='': script=a; script_i=i+1; break
        if a=='-v': show_ver=True; actions.append(('version',None)); i+=1
        elif a=='-i': interactive=True; i+=1
        elif a=='-E': ignore_env=True; i+=1
        elif a.startswith('-e'):
            chunk=a[2:] if len(a)>2 else None
            if chunk=='': chunk=None
            if chunk is None:
                i+=1
                if i>=len(args): print_usage(prog); return 1
                chunk=args[i]
            actions.append(('exec',chunk)); i+=1
        elif a.startswith('-l'):
            name=a[2:] if len(a)>2 else None
            if not name:
                i+=1
                if i>=len(args): print_usage(prog); return 1
                name=args[i]
            actions.append(('require',name)); i+=1
        elif a.startswith('-O'):
            i+=1
        elif a.startswith('-j'):
            cmd=a[2:] if len(a)>2 else None
            if not cmd:
                i+=1
                if i>=len(args): print_usage(prog); return 1
                cmd=args[i]
            # common controls are accepted as no-ops; unknown too, to be friendly
            i+=1
        elif a=='-b':
            sys.stderr.write(f"{prog}: unknown luaJIT command or jit.* modules not installed\n"); return 1
        else:
            print_usage(prog); return 1
    if script_i is None: script_i=(i+1 if script is not None else len(args)+1)
    # arg table uses full argv including program; script index in argv terms
    if script is not None:
        script_index=script_i
    elif actions:
        # no script: first non-option would be after actions; LuaJIT's arg[0] is first arg after -e if any, otherwise nil; approximate
        script_index=len(args)+1
    else:
        script_index=0
    I.globals.rawset('arg', make_arg_table(argv, script_index))
    if not ignore_env:
        init=os.environ.get('LUA_INIT')
        if init:
            try:
                if init.startswith('@'): I.run_file(init[1:])
                else: I.run_chunk(init,'=(LUA_INIT)')
            except Exception as e: report_error(prog,e); return 1
    try:
        for kind,val in actions:
            if kind=='version': sys.stdout.write(VERSION_LINE+'\n')
            elif kind=='exec': I.run_chunk(val,'(command line)')
            elif kind=='require': I.call_value(I.globals.rawget('require'),[val])
        if script is not None:
            if script=='-': I.run_chunk(sys.stdin.read(),'stdin')
            else: I.run_file(script)
        elif not actions and not sys.stdin.isatty():
            I.run_chunk(sys.stdin.read(),'stdin')
        elif interactive or (not actions and sys.stdin.isatty()):
            run_repl(I,prog)
    except Exception as e:
        report_error(prog,e); return 1
    return 0

if __name__=='__main__':
    sys.exit(main(sys.argv))
