        if a=='-': script='-'; script_i=i+1; break
        if not a.startswith('-') or a=='': script=a; script_i=i+1; break
        if a=='-v': show_ver=True; actions.append(('version',None)); i+=1
        elif a=='-i': interactive=True; i+=1
        elif a=='-E': ignore_env=True; i+=1
        elif a.startswith('-e'):
            chunk=a[2:] if len(a)>2 else None
            if chunk=='': chunk=None
            if chunk is None:
                i+=1
                if i>=len(args): print_usage(prog); return 1
                chunk=args[i]
            actions.append(('exec',chunk)); i+=1
        elif a.startswith('-l'):
